import React, { useState } from 'react';
import './JudgeLogin.css';

const JudgeLogin = ({ 
  onJudgeLogin, 
  setShowJudgeLogin, 
  setIsAdmin, 
  setShowAuth, 
  setCurrentJudge, 
  setAuthPin 
}) => {
  const [pin, setPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showJudgeLogin, setShowJudgeLoginState] = useState(false);
  const [showInfoModal, setShowInfoModal] = useState(false);
  const [language, setLanguage] = useState('en');

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!pin.trim()) {
      setError(language === 'tl' ? 'Mangyaring kang PIN' : 'Please enter your PIN');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Call appropriate login API based on login type
      const response = await fetch('http://localhost/Tabolator_Casestudy/backend/api/judge-login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ pin }),
      });

      const data = await response.json();

      if (data.success) {
        // Login successful - call to appropriate handler
        onJudgeLogin(data.judge);
        setPin('');
      } else {
        setError(language === 'tl' ? 'Maling PIN' : data.message || 'Invalid PIN');
      }
    } catch (err) {
      setError(language === 'tl' ? 'Network error. Subukan muli.' : 'Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleAdminAuth = () => {
    // Simple PIN authentication (in production, this should be secure)
    const adminPin = '1234'; // Change this in production
    if (pin === adminPin) {
      setIsAdmin(true);
      setShowAuth(false);
    } else {
      alert('Invalid PIN. Please try again.');
    }
  };

  const handleJudgeLogin = (judgeData) => {
    setCurrentJudge(judgeData);
    setShowJudgeLoginState(false);
    setShowAuth(false);
  };

  const handleLogout = () => {
    setIsAdmin(false);
    setShowAuth(true);
    setCurrentJudge(null);
    setShowJudgeLoginState(false);
    setAuthPin('');
  };

  const handleBackToAuth = () => {
    setShowAuth(true);
    setShowJudgeLoginState(false);
    setCurrentJudge(null);
  };

  const handleInfoModal = () => {
    setShowInfoModal(true);
  };

  const handleCloseModal = () => {
    setShowInfoModal(false);
  };

  return (
    <>
      <div className="judge-login-container">
        <div className="judge-login-card">
