              <div className="option-icon">
                <i className="fi fi-rr-shield-check"></i>
              </div>
              <div className="option-content">
                <h3>{language === 'tl' ? 'Judge na Login' : 'Judge Access'}</h3>
                <p>{language === 'tl' ? 'Enter your judge PIN' : 'Enter your judge PIN'}</p>
              </div>
            </div>
          </div>

          {!showJudgeLogin ? (
            // Admin Login Form
            <div className="auth-form">
              <label htmlFor="adminPin">{language === 'tl' ? 'Enter Admin PIN:' : 'Enter Admin PIN:'}</label>
              <input
                type="password"
                id="adminPin"
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                placeholder={language === 'tl' ? 'Enter 4-digit PIN' : 'Enter 4-digit PIN'}
                maxLength="4"
                onKeyPress={(e) => e.key === 'Enter' && handleAdminAuth()}
              />
              <button className="auth-submit-btn" onClick={handleAdminAuth}>
                <i className="fi fi-rr-lock"></i>
                {language === 'tl' ? 'Login as Admin' : 'Login as Admin'}
              </button>
            </div>
          ) : (
            // Judge Login Form - Same design as admin
            <div className="auth-form">
              <label htmlFor="judgePin">{language === 'tl' ? 'Enter Judge PIN:' : 'Enter Judge PIN:'}</label>
              <input
                type="password"
                id="judgePin"
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                placeholder={language === 'tl' ? 'Enter 4-digit PIN' : 'Enter 4-digit PIN'}
                maxLength="4"
                onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
              />
              <button className="auth-submit-btn" onClick={handleLogin}>
                <i className="fi fi-rr-lock"></i>
                {language === 'tl' ? 'Login as Judge' : 'Login as Judge'}
              </button>
            </div>
