                      <li>{language === 'tl' ? 'Pagmamahala sa mga criteria' : 'Criteria Management'}</li>
                      <li>{language === 'tl' ? 'Pagmamahala sa mga categories' : 'Category Management'}</li>
                      <li>{language === 'tl' ? 'Real-time scoring system' : 'Real-time Scoring System'}</li>
                      <li>{language === 'tl' ? 'Multi-language support' : 'Multi-language Support'}</li>
                    </ul>
                  </div>
                </div>
                <div className="info-item">
                  <div className="info-icon">
                    <i className="fi fi-rr-shield-check"></i>
                  </div>
                  <div className="info-text">
                    <h4>{language === 'tl' ? 'Seguridad' : 'Security'}</h4>
                    <ul>
                      <li>{language === 'tl' ? 'Secure na PIN-based authentication' : 'Secure PIN-based authentication'}</li>
                      <li>{language === 'tl' ? 'Proteksyon ng data' : 'Data Protection'}</li>
                      <li>{language === 'tl' ? 'Role-based access control' : 'Role-based Access Control'}</li>
                      <li>{language === 'tl' ? 'Audit trail ng mga user' : 'User Audit Trail'}</li>
                    </ul>
                  </div>
                </div>
                <div className="info-item">
                  <div className="info-icon">
                    <i className="fi fi-rr-users"></i>
                  </div>
                  <div className="info-text">
                    <h4>{language === 'tl' ? 'Suporta' : 'Support'}</h4>
